import itertools,json
jobs='ABCDE'; published='ACEBD'
slot=dict(zip(jobs,[[4,8,0,2,0],[6,4,5,0,5],[2,6,4,6,0],[8,7,9,6,0],[3,3,1,6,5]]))
t=dict(zip(jobs,[[0,1,1,3,1],[5,0,2,4,2],[3,1,0,0,3],[5,4,4,0,5],[5,0,3,4,0]]))
def distance(q):
 perm=[published.index(x) for x in q]; seen=set(); cycles=0
 for i in range(5):
  if i not in seen:
   cycles+=1;j=i
   while j not in seen: seen.add(j);j=perm[j]
 return 5-cycles
classes={d:[] for d in range(3)}
for p in itertools.permutations(jobs):
 d=distance(p)
 if d>2 or p.index('A')>p.index('D') or p[1]=='E' or p[4]=='D' or p[2]=='E':continue
 nominal=sum(slot[x][i] for i,x in enumerate(p))+sum(t[a][jobs.index(b)] for a,b in zip(p,p[1:]))
 cost=nominal+6*max(0,p.index('A')-1)+4*d+(5 if d==2 else 0)
 classes[d].append((cost,''.join(p)))
best=min(v for vs in classes.values() for v in vs)
print(json.dumps({'roster':best[1],'score':best[0],'best_by_swaps':{str(d):min(vs)[0] if vs else None for d,vs in classes.items()},'feasible_by_swaps':{str(d):len(vs) for d,vs in classes.items()}}))
# Verify distance by independent breadth-first enumeration of exchanges.
levels=[{published}];seen={published}
for d in range(2):
 nxt=set()
 for p in levels[-1]:
  for i,j in itertools.combinations(range(5),2):
   q=list(p);q[i],q[j]=q[j],q[i];q=''.join(q)
   if q not in seen:nxt.add(q)
 levels.append(nxt);seen.update(nxt)
for d,level in enumerate(levels):
 assert all(distance(q)==d for q in level)
 feasible=[q for q in level if q.index('A')<q.index('D') and q[1]!='E' and q[4]!='D' and q[2]!='E']
 assert set(feasible)==set(q for c,q in classes[d])
print('BFS checks passed')

